<?php declare(strict_types=1);namespace App\Infrastructure\Arena;use App\Infrastructure\Persistence\Doctrine\Arena\Entity\DuelPlayerRecord;use Doctrine\ORM\EntityManagerInterface;final class ArenaRealtimePublisher{public function __construct(private readonly EntityManagerInterface $em,private readonly string $endpoint='http://realtime:9010/internal/events'){}public function publish(string $duelId):void{foreach($this->em->getRepository(DuelPlayerRecord::class)->findBy(['duelId'=>$duelId]) as $player){$payload=json_encode(['userId'=>$player->userId,'duelId'=>$duelId,'status'=>'UPDATED'],JSON_THROW_ON_ERROR);$context=stream_context_create(['http'=>['method'=>'POST','header'=>"Content-Type: application/json\r\nX-Realtime-Secret: ".(getenv('REALTIME_INTERNAL_SECRET')?:getenv('JWT_SECRET'))."\r\n",'content'=>$payload,'timeout'=>1,'ignore_errors'=>true]]);@file_get_contents($this->endpoint,false,$context);}}}
